window.VAN_DATA.simulator = {"wheat":{"base":60,"baseLabel":"What a good progressive farmer achieves","levers":[{"name":"Macronutrient Nutrition (N-P-K)","w":15,"bad":"Lowest of N%, P%, or K% delivered vs. recommended dose is below 60%","ok":"Lowest of N%, P%, or K% delivered is 60-90% of recommended dose","best":"Lowest of N%, P%, or K% delivered is 90%+ of recommended dose, and balanced"},{"name":"Irrigation Management","w":15,"bad":"Crown Root Initiation (CRI) irrigation missed or badly delayed, or post-anthesis (grain-filling) irrigation missed","ok":"CRI and post-anthesis both covered, but tillering or jointing irrigation missed or delayed","best":"All critical-stage irrigations delivered on schedule: CRI, tillering, jointing, flowering, grain-filling"},{"name":"Seed Rate / Plant Population","w":10,"bad":"Achieved plant stand below 70% or above 130% of the 30-35 plants/m2 target","ok":"Achieved stand 70-90% or 110-130% of target","best":"Achieved stand within 90-110% of the 30-35 plants/m2 target"},{"name":"Weed Management","w":9,"bad":"No effective weed control applied; weeds left uncontrolled through the season","ok":"Weed control applied but delayed or incomplete relative to the ~60-75 day critical weed-free period","best":"Field kept effectively weed-free through the critical ~60-75 day post-sowing period (pre- and/or post-emergence control)"},{"name":"Disease Management (rust and other foliar disease)","w":10,"bad":"Susceptible variety grown; no monitoring or fungicide control despite visible disease pressure","ok":"Moderately susceptible variety, or fungicide applied late, only after visible spread","best":"Resistant or tolerant variety used, with active monitoring and timely fungicide application at first sign of infection"},{"name":"Genetics & Seed Quality","w":13,"bad":"Uncertified or farmer-saved seed, unknown or non-recommended variety, not cleaned or treated","ok":"Good-quality farmer-saved seed of a recommended variety, cleaned or graded, but not certified or treated","best":"Certified seed of a recommended, locally-adapted variety, treated with fungicide or insecticide before sowing"},{"name":"Sowing Time","w":11,"bad":"Sown more than ~2 weeks outside the optimal window (very early October, or December onward)","ok":"Sown within ~2 weeks before or after the optimal window","best":"Sown within the optimal window (Punjab: 1-20 November)"},{"name":"Micronutrient Nutrition & Soil Fertility Baseline","w":9,"bad":"No micronutrient (Zn/B) application on soil known or likely to be deficient (typical Punjab calcareous soil)","ok":"Partial or inconsistent micronutrient application, or none applied where soil status is unconfirmed","best":"Zn (and B where indicated) applied at the recommended rate on soil known or likely to be deficient"},{"name":"Insect-Pest Management (mainly aphids)","w":5,"bad":"No field scouting or control despite aphid presence","ok":"Reactive control after visible infestation, incomplete coverage","best":"Regular field scouting with timely insecticide or botanical control at threshold aphid levels"},{"name":"Lodging & Harvest Risk","w":3,"bad":"Significant lodging observed (especially before or during grain filling), or harvest significantly delayed past maturity","ok":"Minor or partial lodging in small patches, or slight harvest delay, with limited impact","best":"No lodging observed; balanced N and a lodging-resistant variety used; harvested at physiological maturity"}]},"potato":{"base":300,"baseLabel":"Sahiwal White","levers":[{"name":"Seed Tuber Quality & Source","w":20,"bad":"Uncertified or farmer-saved seed, multiple generations since the last certified or clean source, no inspection or rogueing","ok":"Farmer-saved seed but 1st–2nd generation from a known clean or certified source, visually inspected and rogued","best":"Certified or quality-declared seed tubers from a recognised, disease-tested or virus-indexed source"},{"name":"Disease Management (late blight and other field disease)","w":18,"bad":"Susceptible variety, no fungicide programme, no field monitoring despite cool, humid blight weather","ok":"Fungicide applied reactively after visible late blight symptoms; monitoring only moderate","best":"Preventive programme run through the cool-humid spells, active field scouting, and a less-susceptible variety where one is available"},{"name":"Irrigation Management","w":15,"bad":"Tuber initiation or bulking irrigation missed or badly delayed, or the ridge waterlogged","ok":"Minor delay or unevenness during initiation or bulking, but nothing missed outright","best":"Soil moisture held steady through tuber initiation and bulking - never allowed below about 60% of available moisture, and never waterlogged"},{"name":"Macronutrient Nutrition (potash and nitrogen timing)","w":12,"bad":"Potash well below the local optimum, or nitrogen timing ignored - heavy late nitrogen delaying maturity","ok":"Potash applied at part of the optimum; nitrogen reasonably timed but not split to match peak demand","best":"Potash applied at the optimum for calcareous ground, with nitrogen split to match peak demand at tuber bulking (roughly 42-70 days after planting)"},{"name":"Insect-Pest Management (aphids and tuber moth)","w":10,"bad":"No scouting and no control, with aphids or tuber moth present in the crop","ok":"Insecticide applied only after visible infestation or damage","best":"Regular scouting with timely control - early-season aphid control to limit virus spread, and enough soil cover on the ridge to keep tuber moth off the tubers"},{"name":"Hilling / Earthing-Up and Land Preparation","w":6,"bad":"Not hilled, or hilled so late that tubers were exposed and greened","ok":"Hilled, but late or with incomplete cover","best":"Ridges built up at the right stage and kept up, with no tuber exposed to light"},{"name":"Micronutrient and Soil Fertility (calcium, zinc, boron)","w":6,"bad":"No micronutrient applied on soil known or likely to be short - typical Punjab calcareous ground","ok":"Micronutrient applied partially or inconsistently","best":"Calcium, zinc and boron applied against a soil test or the known regional deficiency pattern"},{"name":"Seed Rate / Plant Spacing","w":5,"bad":"Spacing or seed rate far outside the recommended range - overcrowded or too sparse - leaving a poor stand","ok":"Moderate deviation from the recommended spacing or seed rate","best":"Within the recommended spacing and seed rate for the variety and the seed tuber size used"},{"name":"Planting Time","w":5,"bad":"Planted well outside the recommended window for the area - risking frost at emergence or heat at tuberisation","ok":"Planted slightly outside the optimal window","best":"Planted inside the recommended window for that season and growing area, autumn or spring"},{"name":"Harvest Timing and Post-Harvest Handling","w":3,"bad":"Harvest well past maturity, or tubers stored without curing or ventilation - weight loss, sprouting or moth damage follows","ok":"Timing reasonable but curing or storage practice incomplete","best":"Lifted at physiological maturity, properly cured, and stored somewhere ventilated at the right temperature"}]}};
